// Features/Reservations/CreateReservation.cs
public static class CreateReservation
{
    public sealed record Command(Guid TableId, DateTime Start, int Guests);

    public static void Map(IEndpointRouteBuilder app) =>
        app.MapPost("/reservations", Handle);

    static async Task<IResult> Handle(Command cmd, AppDbContext db, CancellationToken ct)
    {
        var table = await db.Tables.FindAsync([cmd.TableId], ct);
        if (table is null) return Results.NotFound();
        var reservation = table.Reserve(cmd.Start, cmd.Guests); // reguły w domenie
        await db.SaveChangesAsync(ct);
        return Results.Created($"/reservations/{reservation.Id}", new { reservation.Id });
    }
}

// Value object: porównanie po wartości, niemutowalny, sam się waliduje
public sealed record Money
{
    public decimal Amount { get; }
    public string Currency { get; }

    public Money(decimal amount, string currency)
    {
        if (amount < 0) throw new DomainException("Kwota nie może być ujemna");
        if (currency.Length != 3) throw new DomainException("Kod waluty ma 3 litery");
        (Amount, Currency) = (amount, currency.ToUpperInvariant());
    }

    public Money Add(Money other) => other.Currency == Currency
        ? new Money(Amount + other.Amount, Currency)
        : throw new DomainException("Różne waluty");
}

