// DOBRZE: aggregate root pilnuje niezmienników
public sealed class Order : AggregateRoot
{
    private readonly List<OrderLine> _lines = [];
    public IReadOnlyList<OrderLine> Lines => _lines;
    public OrderStatus Status { get; private set; } = OrderStatus.Draft;

    public void AddLine(ProductId productId, int qty, Money price)
    {
        if (Status != OrderStatus.Draft) throw new DomainException("Zamówienie już złożone");
        if (_lines.Count >= 50) throw new DomainException("Maksymalnie 50 pozycji");
        _lines.Add(new OrderLine(productId, qty, price));
    }

    public void Submit()
    {
        if (_lines.Count == 0) throw new DomainException("Puste zamówienie");
        Status = OrderStatus.Submitted;
        Raise(new OrderSubmitted(Id, DateTime.UtcNow));
    }
}

