public sealed class PlaceOrderHandler(AppDbContext db)
{
    public async Task<Guid> Handle(PlaceOrder cmd, CancellationToken ct)
    {
        var order = Order.Create(cmd.CustomerId, cmd.Lines); // walidacja i niezmienniki
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct);
        return order.Id;
    }
}

// ZAPYTANIE: prosto i szybko, bez agregatów
public sealed class GetMyOrdersHandler(AppDbContext db)
{
    public Task<List<OrderListItem>> Handle(Guid customerId, CancellationToken ct) =>
        db.Orders.AsNoTracking()
          .Where(o => o.CustomerId == customerId)
          .OrderByDescending(o => o.CreatedAt)
          .Select(o => new OrderListItem(o.Id, o.CreatedAt, o.Total.Amount, o.Status.ToString()))
          .ToListAsync(ct);
}

public sealed class BankAccount
{
    public Guid Id { get; private set; }
    public decimal Balance { get; private set; }
    public int Version { get; private set; }

    // stan wyliczany z historii
    public static BankAccount Load(IEnumerable<object> history)
    {
        var acc = new BankAccount();
        foreach (var e in history) acc.Apply(e);
        return acc;
    }

    private void Apply(object e)
    {
        if (e is AccountOpened o) Id = o.AccountId;
        else if (e is MoneyDeposited d) Balance += d.Amount;
        else if (e is MoneyWithdrawn w) Balance -= w.Amount;
        Version++; // numer wersji do optimistic concurrency
    }
}

app.MapGet("/{code}", async (string code, HybridCache cache, AppDbContext db,
    IClickQueue clicks, HttpContext http, CancellationToken ct) =>
{
    // 1. cache (pamięć + Redis), przy braku – zapytanie do bazy
    var url = await cache.GetOrCreateAsync($"link:{code}", async token =>
        await db.Links.AsNoTracking()
            .Where(l => l.Code == code && (l.ExpiresAt == null || l.ExpiresAt > DateTime.UtcNow))
            .Select(l => l.LongUrl)
            .FirstOrDefaultAsync(token), cancellationToken: ct);

    if (url is null) return Results.NotFound();

    // 2. statystyka asynchronicznie – nie blokuje przekierowania
    await clicks.EnqueueAsync(new Click(code, DateTime.UtcNow, http.Request.Headers.Referer), ct);

    // 3. 302, żeby każde kliknięcie przechodziło przez nas
    return Results.Redirect(url, permanent: false);
});
